    conv.forward(input);

    std::cout << "\n===== CONV OUTPUT 26x26 =====\n";
    Matrix::log_static(conv.outputs, 26, 26, 'C');

    // ---- Pool ----
    pool.forward(conv.outputs);

    std::cout << "\n===== POOL OUTPUT 13x13 =====\n";
    Matrix::log_static(pool.outputs, 13, 13, 'P');

    // ---- Dense ----
    dense.forward(pool.outputs);

