    // =====================================================
    // BACKWARD
    // =====================================================

    std::cout << "\n=========== BACKWARD ===========\n";

    // ---- Dense backward ----

    float loss_grad[10];
    for (int i = 0; i < 10; ++i) {
        loss_grad[i] = target[i] - dense.outputs[i];
    }

    float* grad_dense = dense.backward(pool.outputs, loss_grad);

    std::cout << "\n===== DENSE dInput (169) =====\n";
    Matrix::log_static(grad_dense, 1, 169, 'd');

    // ---- Pool backward ----
    float* grad_pool = pool.backward(conv.outputs, grad_dense);

    std::cout << "\n===== POOL dInput (26x26) =====\n";
    Matrix::log_static(grad_pool, 26, 26, 'p');

    // ---- Conv backward ----
    float* grad_conv = conv.backward(input, grad_pool);

    std::cout << "\n===== CONV dInput (28x28) =====\n";
    Matrix::log_static(grad_conv, 28, 28, 'c');

